<script setup lang="ts">
import {ref,reactive,onMounted} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {request} from '@/integration/service';
const rows=ref([]),busy=ref(false),form=reactive({username:'',name:'',password:''});
async function load(){rows.value=await request('/api/admin/users');}
async function create(){busy.value=true;try{await request('/api/admin/users','POST',form);Object.assign(form,{username:'',name:'',password:''});ElMessage.success('读者已创建');await load();}finally{busy.value=false;}}
async function toggle(row){await request('/api/admin/users/'+row.id,'PUT',{disabled:!row.disabled});await load();}
async function reset(row){try{const {value}=await ElMessageBox.prompt('至少 10 位，重置后该读者需要重新登录','重置 '+row.name+' 的密码',{inputType:'password',inputValidator:v=>v?.length>=10||'密码至少 10 位'});await request('/api/admin/users/'+row.id,'PUT',{password:value});ElMessage.success('密码已重置');}catch(e){if(e!=='cancel'&&e!=='close')return;}}
onMounted(load);
</script>
<template><el-card><template #header><h2>读者管理</h2></template><el-alert title="读者账号仅用于个人资料与留言；文章、说说、相册和私宅均由站主管理。旧账号及其历史内容保留。" :closable="false"/><el-form label-position="top" class="my-4" @submit.prevent="create"><el-form-item label="用户名（3–32 位小写字母、数字、下划线或短横线）"><el-input v-model="form.username" required autocomplete="off"/></el-form-item><el-form-item label="显示名称"><el-input v-model="form.name" required/></el-form-item><el-form-item label="初始密码（至少 10 位）"><el-input v-model="form.password" required minlength="10" type="password" show-password autocomplete="new-password"/></el-form-item><el-button native-type="submit" type="primary" :loading="busy">创建读者</el-button></el-form><el-table :data="rows"><el-table-column prop="username" label="用户名"/><el-table-column prop="name" label="显示名称"/><el-table-column label="状态"><template #default="{row}">{{row.disabled?'已停用':'正常'}}</template></el-table-column><el-table-column label="操作" min-width="190"><template #default="{row}"><el-button size="small" @click="toggle(row)">{{row.disabled?'启用':'停用'}}</el-button><el-button size="small" @click="reset(row)">重置密码</el-button></template></el-table-column></el-table></el-card></template>
